CREATE TABLE public.meeting_bans (meeting_id uuid NOT NULL REFERENCES public.meetings(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, banned_by uuid NOT NULL REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (meeting_id,user_id));
GRANT SELECT ON public.meeting_bans TO authenticated;
GRANT ALL ON public.meeting_bans TO service_role;
ALTER TABLE public.meeting_bans ENABLE ROW LEVEL SECURITY;
CREATE POLICY meeting_bans_manager_read ON public.meeting_bans FOR SELECT TO authenticated USING (public.meeting_is_manager(meeting_id,auth.uid()) OR user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.meeting_can_enter(_id uuid, _uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _uid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.meeting_bans b WHERE b.meeting_id=_id AND b.user_id=_uid) AND EXISTS(SELECT 1 FROM public.meetings m WHERE m.id=_id AND m.status NOT IN ('cancelada','encerrada') AND (public.meeting_is_manager(_id,_uid) OR (NOT m.room_locked AND (m.access_type='aberto' OR EXISTS(SELECT 1 FROM public.meeting_participants p WHERE p.meeting_id=_id AND p.user_id=_uid AND p.status IN ('convidado','aprovado')) OR EXISTS(SELECT 1 FROM public.meeting_access_requests ar WHERE ar.meeting_id=_id AND ar.user_id=_uid AND ar.status='aprovado') OR (m.scope='curso' AND EXISTS(SELECT 1 FROM public.enrollments e WHERE e.course_id=m.course_id AND e.user_id=_uid)))))) $$;
CREATE OR REPLACE FUNCTION public.meeting_remove_participant(_id uuid, _target uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.meeting_is_manager(_id,auth.uid()) OR public.meeting_is_manager(_id,_target) OR _target=auth.uid() OR NOT EXISTS(SELECT 1 FROM public.meetings WHERE id=_id AND status='em_andamento') THEN RAISE EXCEPTION 'Sem permissão para remover participante'; END IF; INSERT INTO public.meeting_bans(meeting_id,user_id,banned_by) VALUES(_id,_target,auth.uid()) ON CONFLICT(meeting_id,user_id) DO NOTHING; UPDATE public.meeting_sessions SET left_at=now(),duration_seconds=GREATEST(0,extract(epoch FROM (LEAST(now(),last_seen_at+interval '45 seconds')-joined_at))::int) WHERE meeting_id=_id AND user_id=_target AND left_at IS NULL; INSERT INTO public.meeting_audit(meeting_id,actor_id,action,details) VALUES(_id,auth.uid(),'participante_removido',jsonb_build_object('user_id',_target)); END $$;
REVOKE ALL ON FUNCTION public.meeting_remove_participant(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.meeting_remove_participant(uuid,uuid) TO authenticated,service_role;